'use client';

import { useParams } from 'next/navigation';
import { CheckCircle2, ClipboardList, Clock3, Edit3, IndianRupee, Plus, Star, Users, UtensilsCrossed } from 'lucide-react';
import { PanelShell, MetricCard, type PanelNavItem } from '@/components/panels/panel-shell';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { restaurants, orders, formatPrice } from '@/lib/data';
import { toast } from 'sonner';
const nav: PanelNavItem[] = [{ href: '/vendor', label: 'Dashboard', icon: ClipboardList }, { href: '/vendor/orders', label: 'Orders', icon: ClipboardList }, { href: '/vendor/menu', label: 'Menu', icon: UtensilsCrossed }, { href: '/vendor/categories', label: 'Categories', icon: UtensilsCrossed }, { href: '/vendor/offers', label: 'Offers', icon: Star }, { href: '/vendor/customers', label: 'Customers', icon: Users }, { href: '/vendor/reviews', label: 'Reviews', icon: Star }, { href: '/vendor/analytics', label: 'Analytics', icon: IndianRupee }, { href: '/vendor/profile', label: 'Restaurant Profile', icon: Edit3 }, { href: '/vendor/settings', label: 'Settings', icon: Clock3 }];
export default function VendorSubPage() { const params = useParams(); const slug = Array.isArray(params.slug) ? params.slug.join('/') : String(params.slug ?? 'orders'); const title = slug.split('/').pop()?.replace(/-/g, ' ') ?? 'orders'; const restaurant = restaurants[0]; const menu = restaurant.menu; return <PanelShell title={title.charAt(0).toUpperCase() + title.slice(1)} subtitle="Manage your restaurant operations from one place." brand="FoodGo Partner" navItems={nav}><div className="flex flex-wrap items-center justify-between gap-4"><div><h2 className="font-display text-2xl font-bold">{title === 'orders' ? 'Incoming orders' : title === 'menu' ? 'Menu management' : `${title} workspace`}</h2><p className="mt-1 text-sm text-muted-foreground">{title === 'orders' ? 'Accept, prepare and update order status.' : 'Keep your restaurant information current.'}</p></div><Button onClick={() => toast.success('Create form opened')}><Plus className="mr-2 h-4 w-4" /> Add new</Button></div>{title === 'orders' ? <div className="mt-6 space-y-3">{orders.map((order) => <div key={order.id} className="flex flex-wrap items-center gap-4 rounded-2xl border border-border/60 bg-card p-5"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><ClipboardList className="h-5 w-5" /></div><div className="flex-1"><p className="font-semibold">{order.id} • Customer order</p><p className="mt-1 text-sm text-muted-foreground">{order.items.map((item) => `${item.quantity} × ${item.name}`).join(', ')}</p></div><span className="text-sm font-bold">{formatPrice(order.total)}</span><span className="rounded-full bg-warning/10 px-3 py-1 text-xs font-semibold text-warning">{order.status}</span><Button size="sm" onClick={() => toast.success('Order status updated')}>Update</Button></div>)}</div> : title === 'menu' ? <div className="mt-6 overflow-hidden rounded-2xl border border-border/60 bg-card"><div className="grid grid-cols-[1fr_auto_auto_auto] gap-4 border-b border-border bg-muted/40 p-4 text-xs font-semibold uppercase tracking-wide text-muted-foreground"><span>Item</span><span>Category</span><span>Price</span><span>Action</span></div>{menu.map((item) => <div key={item.id} className="grid grid-cols-[1fr_auto_auto_auto] items-center gap-4 border-b border-border p-4 last:border-0"><div className="flex items-center gap-3"><img src={item.image} alt="" className="h-10 w-10 rounded-lg object-cover" /><span className="text-sm font-medium">{item.name}</span></div><span className="text-sm text-muted-foreground">{item.category}</span><span className="text-sm font-semibold">{formatPrice(item.price)}</span><Button variant="ghost" size="sm" onClick={() => toast.success('Item editor opened')}>Edit</Button></div>)}</div> : <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><MetricCard label="Active listings" value={String(menu.length)} change="All information up to date" icon={UtensilsCrossed} /><MetricCard label="Customers" value="1,842" change="+12% this month" icon={Users} /><MetricCard label="Reviews" value="4.7 / 5" change="92% positive" icon={Star} /></div>}</PanelShell>; }
